#define TEXT 256
static const char *arg(int argc,char **argv,const char *name){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static int token(const char *s,size_t max){if(!s||!*s||strlen(s)>=max)return 0;for(const unsigned char *p=(const unsigned char*)s;*p;p++)if(!((*p>='a'&&*p<='z')||(*p>='A'&&*p<='Z')||(*p>='0'&&*p<='9')||strchr(":._/@-",*p)))return 0;return 1;}
static int iso(const char *s){return s&&strlen(s)==20&&s[4]=='-'&&s[7]=='-'&&s[10]=='T'&&s[13]==':'&&s[16]==':'&&s[19]=='Z';}
static int not_future(const char *s){struct tm tm={0};if(!iso(s)||!strptime(s,"%Y-%m-%dT%H:%M:%SZ",&tm))return 0;time_t at=timegm(&tm),now=time(NULL);return at!=(time_t)-1&&at<=now+300;}
static int unhex(const char *hex,unsigned char *out,size_t bytes){return hex&&strlen(hex)==bytes*2&&sodium_hex2bin(out,bytes,hex,bytes*2,NULL,NULL,NULL)==0;}
static BfProtocolRoleSpec role(const char *name,const char *authority,const char *const *requires,size_t rc,const char *const *produces,size_t pc){BfProtocolRoleSpec s={0};s.name=name;s.authority=authority;s.requires=requires;s.requires_count=rc;s.produces=produces;s.produces_count=pc;return s;}
static int exact_existing(sqlite3 *db,const char *id,const char *committer,const char *beneficiary,const char *resource,const char *conditions,const char *authority,const char *origin,const char *enactment){sqlite3_stmt *s=NULL;int ok=0;if(sqlite3_prepare_v2(db,"SELECT committer,beneficiary,resource,conditions,authority,origin,enactment FROM commitments WHERE commitment_id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW)ok=!strcmp((const char*)sqlite3_column_text(s,0),committer)&&!strcmp((const char*)sqlite3_column_text(s,1),beneficiary)&&!strcmp((const char*)sqlite3_column_text(s,2),resource)&&!strcmp((const char*)sqlite3_column_text(s,3),conditions)&&!strcmp((const char*)sqlite3_column_text(s,4),authority)&&!strcmp((const char*)sqlite3_column_text(s,5),origin)&&!strcmp((const char*)sqlite3_column_text(s,6),enactment);sqlite3_finalize(s);return ok;}
static int tag_origin(sqlite3 *db,const char *id,const char *enactment,const char *origin){sqlite3_stmt *s=NULL;int ok=0;if(sqlite3_prepare_v2(db,"UPDATE commitments SET origin=?1 WHERE commitment_id=?2 AND enactment=?3",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,origin,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,enactment,-1,SQLITE_TRANSIENT);ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(db)==1;sqlite3_finalize(s);return ok;}
static int signature_ok(const char *seller,const char *signature,const char *statement){const char *prefix="ed25519:";unsigned char pk[crypto_sign_PUBLICKEYBYTES],sig[crypto_sign_BYTES],digest[crypto_hash_sha256_BYTES];if(strncmp(seller,prefix,strlen(prefix))||!unhex(seller+strlen(prefix),pk,sizeof(pk))||!unhex(signature,sig,sizeof(sig)))return 0;crypto_hash_sha256(digest,(const unsigned char*)statement,strlen(statement));return crypto_sign_verify_detached(sig,digest,sizeof(digest),pk)==0;}
static int open_db(const char *path,sqlite3 **db){if(!path||sqlite3_open_v2(path,db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,NULL)!=SQLITE_OK){sqlite3_close(*db);*db=NULL;return 0;}sqlite3_busy_timeout(*db,5000);return 1;}
static void json_text(const char *s){putchar('"');for(;*s;s++){unsigned char c=(unsigned char)*s;if(c=='"'||c=='\\'){putchar('\\');putchar(c);}else if(c>=0x20)putchar(c);}putchar('"');}

int bf_procurement_effect_main(int argc,char **argv){
 if(sodium_init()<0){fputs("refused: crypto unavailable\n",stderr);return 1;}
 const char *cpath=arg(argc,argv,"--commitments-db"),*apath=arg(argc,argv,"--authority-db"),*requested_exchange=arg(argc,argv,"--exchange"),*order=arg(argc,argv,"--order-intent-digest"),*qid=arg(argc,argv,"--quote-id"),*qd=arg(argc,argv,"--quote-digest"),*supplier=arg(argc,argv,"--supplier-id"),*cap=arg(argc,argv,"--capability"),*buyer=arg(argc,argv,"--buyer"),*seller=arg(argc,argv,"--seller"),*settlement=arg(argc,argv,"--settlement"),*deliverer=arg(argc,argv,"--deliverer"),*amount=arg(argc,argv,"--amount-cents"),*currency=arg(argc,argv,"--currency"),*signature=arg(argc,argv,"--signature"),*at=arg(argc,argv,"--at");
 if(!cpath||!apath||!token(requested_exchange,TEXT)||!token(order,65)||strlen(order)!=64||!token(qid,TEXT)||!token(qd,65)||strlen(qd)!=64||!token(supplier,TEXT)||!token(cap,512)||!token(buyer,TEXT)||!token(seller,TEXT)||!token(settlement,TEXT)||!token(deliverer,TEXT)||!token(currency,4)||strlen(currency)!=3||!signature||strlen(signature)!=128||!not_future(at)){fputs("refused: incomplete, unbounded or future-dated enactment request\n",stderr);return 2;}
 if(strcmp(supplier,seller)||strncmp(seller,"ed25519:",8)||strlen(seller)!=72){fputs("refused: supplier identity is not directly bound to the signing seller actor\n",stderr);return 3;}
 char *end=NULL;long long cents=strtoll(amount?amount:"",&end,10);if(!amount||!end||*end||cents<0||cents>9007199254740991LL){fputs("refused: invalid exact amount\n",stderr);return 2;}
 const char *keys[]={"order_intent","quote","capability","buyer","seller","settlement","deliverer"};
 bf_jv *values[]={bf_jv_str(order),bf_jv_str(qd),bf_jv_str(cap),bf_jv_str(buyer),bf_jv_str(seller),bf_jv_str(settlement),bf_jv_str(deliverer)};
 char basis[65],exchange[96];bf_jv_digest_members(BF_JV_SORT_BYTES,7,keys,(const bf_jv *const *)values,basis);for(size_t i=0;i<7;i++)bf_jv_free(values[i]);
 snprintf(exchange,sizeof exchange,"procurement:%.*s",48,basis);if(strcmp(exchange,requested_exchange)){fputs("refused: exchange does not match exact procurement tuple\n",stderr);return 3;}
 char statement[4096];int n=snprintf(statement,sizeof statement,"bonfyre.procurement.supplier-acceptance.v1\nexchange=%s\norder_intent_digest=%s\nquote_id=%s\nquote_digest=%s\nsupplier_id=%s\ncapability=%s\nbuyer=%s\nseller=%s\nsettlement=%s\ndeliverer=%s\namount_cents=%lld\ncurrency=%s\naccepted_at=%s\n",exchange,order,qid,qd,supplier,cap,buyer,seller,settlement,deliverer,cents,currency,at);
 if(n<0||(size_t)n>=sizeof statement||!signature_ok(seller,signature,statement)){fputs("refused: supplier acceptance signature is invalid\n",stderr);return 4;}
 char money[128];n=snprintf(money,sizeof money,"money:%s:%lld",currency,cents);if(n<0||(size_t)n>=sizeof money)return 2;
 BfProtocolContract contract;BfProtocolRoleSpec spec;BfProtocolCommitmentSpec commitment;const char *br[]={"capability","buyer_identity"},*bp[]={"request"},*sr[]={"request"},*sp[]={"quote"},*tr[]={"quote"},*tp[]={"acceptance"},*dr[]={"acceptance"},*dp[]={"delivery"};
 bf_protocol_contract_init(&contract,"quote-accept");if(bf_protocol_contract_given(&contract,"capability")||bf_protocol_contract_given(&contract,"buyer_identity")||bf_protocol_contract_key(&contract,"exchange_id"))return 1;
 spec=role("buyer","request:capability",br,2,bp,1);if(bf_protocol_contract_role(&contract,&spec))return 1;spec=role("seller","quote:capability",sr,1,sp,1);if(bf_protocol_contract_role(&contract,&spec))return 1;spec=role("settlement","accept:quote",tr,1,tp,1);if(bf_protocol_contract_role(&contract,&spec))return 1;spec=role("deliverer","deliver:capability",dr,1,dp,1);if(bf_protocol_contract_role(&contract,&spec))return 1;
 commitment=(BfProtocolCommitmentSpec){"delivery","deliverer","buyer",cap,"delivery"};if(bf_protocol_contract_commit(&contract,&commitment))return 1;commitment=(BfProtocolCommitmentSpec){"payment","buyer","seller",money,"acceptance"};if(bf_protocol_contract_commit(&contract,&commitment))return 1;
 sqlite3 *cdb=NULL,*adb=NULL;if(!open_db(cpath,&cdb)||!open_db(apath,&adb)){sqlite3_close(cdb);sqlite3_close(adb);fputs("refused: native effect stores are unavailable\n",stderr);return 1;}
 BfCommitment *graph=NULL;if(bf_commitment_open_database(cdb,&graph,stderr)!=BF_COMMITMENT_OK){sqlite3_close(cdb);sqlite3_close(adb);fputs("refused: commitment owner unavailable\n",stderr);return 1;}bf_commitment_close(graph);
 BfProtocolActor actors[]={{"buyer",buyer},{"seller",seller},{"settlement",settlement},{"deliverer",deliverer}};BfProtocolAuthorityRefusal refusal={0};BfProtocolStatus auth=bf_protocol_contract_authorize(&contract,adb,actors,4,exchange,at,"procurement",&refusal);
 if(auth!=BF_PROTOCOL_OK){fprintf(stderr,"refused: authority missing role=%s actor=%s permission=%s\n",refusal.role,refusal.actor,refusal.permission);sqlite3_close(cdb);sqlite3_close(adb);return 5;}
 char did[BF_COMMITMENT_ID_MAX],pid[BF_COMMITMENT_ID_MAX],origin[96];snprintf(did,sizeof did,"%s:delivery",exchange);snprintf(pid,sizeof pid,"%s:payment",exchange);snprintf(origin,sizeof origin,"procurement-order:%s",order);int ed=exact_existing(cdb,did,deliverer,buyer,cap,"delivery","deliver:capability",origin,exchange),ep=exact_existing(cdb,pid,buyer,seller,money,"acceptance","request:capability",origin,exchange);
 if(ed<0||ep<0||ed!=ep){sqlite3_close(cdb);sqlite3_close(adb);fputs("refused: partial or conflicting prior enactment\n",stderr);return 6;}int replayed=ed&&ep;BfProtocolEnactment enacted={0};
 if(!replayed){if(sqlite3_exec(cdb,"BEGIN IMMEDIATE",NULL,NULL,NULL)!=SQLITE_OK){sqlite3_close(cdb);sqlite3_close(adb);fputs("refused: commitment provenance transaction unavailable\n",stderr);return 1;}BfProtocolStatus st=bf_protocol_contract_enact_authorized(&contract,cdb,adb,exchange,actors,4,exchange,at,"procurement",at,&enacted);if(st!=BF_PROTOCOL_OK){sqlite3_exec(cdb,"ROLLBACK",NULL,NULL,NULL);sqlite3_close(cdb);sqlite3_close(adb);fprintf(stderr,"refused: protocol enactment %s\n",bf_protocol_status_name(st));return 7;}if(!tag_origin(cdb,did,exchange,origin)||!tag_origin(cdb,pid,exchange,origin)||sqlite3_exec(cdb,"COMMIT",NULL,NULL,NULL)!=SQLITE_OK){sqlite3_exec(cdb,"ROLLBACK",NULL,NULL,NULL);sqlite3_close(cdb);sqlite3_close(adb);fputs("refused: exact order-intent provenance could not be committed\n",stderr);return 1;}}else enacted.opened_count=2;
 sqlite3_close(cdb);sqlite3_close(adb);fputs("{\"schema\":\"bonfyre.procurement.enactment-receipt.v1\",\"exchange\":",stdout);json_text(exchange);fputs(",\"order_intent_digest\":",stdout);json_text(order);fputs(",\"quote_id\":",stdout);json_text(qid);fputs(",\"supplier_id\":",stdout);json_text(supplier);printf(",\"supplier_identity_binding_verified\":true,\"supplier_acceptance_verified\":true,\"protocol_enacted\":true,\"commitment_opened\":true,\"opened_count\":%zu,\"replayed\":%s,",enacted.opened_count,replayed?"true":"false");fputs("\"does_not_establish\":\"purchase order, payable, payment presentation, settlement, fulfillment, shipment, receipt, satisfaction or ownership\"}\n",stdout);return 0;
}
